using namespace tigersheets;
void require(bool result,const char* message){if(!result)throw std::runtime_error(message);}
void removePrivateMetadata(const std::string& path){int error=0;auto* archive=zip_open(path.c_str(),0,&error);require(archive!=nullptr,"open native fixture package");const auto index=zip_name_locate(archive,"tigersheets/metadata.json",0);if(index>=0)require(zip_delete(archive,index)==0,"remove optional private settings for native-only proof");require(zip_close(archive)==0,"save native-only fixture");}
void nativePackageRoundtrip(){
 char pattern[]="/tmp/tigersheets-print-native-XXXXXX";const auto* temporary=mkdtemp(pattern);require(temporary,"native print temporary directory");const std::filesystem::path directory(temporary);struct Cleanup{std::filesystem::path directory;~Cleanup(){std::filesystem::remove_all(directory);}} cleanup{directory};
 WorkbookSession session;require(session.apply(0,Json::array({{{"type","add_sheet"},{"id","unused"},{"name","Unused"}},{{"type","set_metadata"},{"key","settings"},{"value",{{"printSheets",{{"sheet-1",{{"area",{{"row1",1},{"col1",1},{"row2",30},{"col2",4}}},{"repeatHeaderRows",{{"row1",1},{"row2",2}}},{"orientation","landscape"},{"fitWidth",true}}}}}}}}})),"native print settings fixture");
 const auto initial=(directory/"initial.xlsx").string();writeWorkbook(initial,session.snapshotView());auto package=readWorkbook(initial);require(package.entries.at("xl/workbook.xml").find("_xlnm.Print_Area")!=std::string::npos,"actual workbook save must emit native print definitions");removePrivateMetadata(initial);package=readWorkbook(initial);require(package.workbook.at("settings").at("printSheets").at("sheet-1").at("area").at("row2")==30,"actual workbook read imports settings without private metadata");
 auto edited=package.workbook;edited["sheets"][0]["name"]="Renamed 'Report";std::swap(edited["sheets"][0],edited["sheets"][1]);const auto reordered=(directory/"reordered.xlsx").string();writeWorkbook(reordered,edited,&package);removePrivateMetadata(reordered);auto moved=readWorkbook(reordered);pugi::xml_document xml;require(xml.load_string(moved.entries.at("xl/workbook.xml").c_str()),"reordered print workbook XML");auto names=xml.document_element().child("definedNames");for(auto node:names.children())if(std::string(node.attribute("name").value()).starts_with("_xlnm.Print_"))require(node.attribute("localSheetId").as_int()==1&&std::string(node.text().as_string()).starts_with("'Renamed ''Report'!"),"rename and reorder remap native print name scope and escaped qualifiers");
 auto reduced=moved.workbook;reduced["sheets"].erase(reduced["sheets"].begin());const auto deleted=(directory/"deleted.xlsx").string();writeWorkbook(deleted,reduced,&moved);removePrivateMetadata(deleted);const auto final=readWorkbook(deleted);pugi::xml_document finalXml;require(finalXml.load_string(final.entries.at("xl/workbook.xml").c_str()),"deleted print workbook XML");for(auto node:finalXml.document_element().child("definedNames").children())if(std::string(node.attribute("name").value()).starts_with("_xlnm.Print_"))require(node.attribute("localSheetId").as_int()==0,"deleting preceding sheets remaps print definition indices");require(final.workbook.at("settings").at("printSheets").size()==1,"deleted sheets must not leave orphan print settings on native import");
}
int main(){try{
 WorkbookPackage package;package.workbook={{"sheets",Json::array({{{"id","report"},{"name","Sales '26"},{"cells",Json::array()}}})},{"settings",Json::object()}};package.sheetParts["report"]="xl/worksheets/sheet1.xml";
 package.entries["xl/workbook.xml"]="<m:workbook xmlns:m='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><m:sheets/><m:definedNames><m:definedName name='_xlnm.Print_Area' localSheetId='0'>'Sales ''26'!$B$2:$E$50</m:definedName><m:definedName name='_xlnm.Print_Titles' localSheetId='0'>'Sales ''26'!$2:$3</m:definedName></m:definedNames></m:workbook>";
 package.entries["xl/worksheets/sheet1.xml"]="<m:worksheet xmlns:m='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><m:sheetPr><m:pageSetUpPr fitToPage='1'/></m:sheetPr><m:sheetData/><m:pageSetup orientation='landscape' fitToWidth='1' fitToHeight='0' paperSize='9'/></m:worksheet>";
 readNativePrintSettings(package);const auto settings=package.workbook.at("settings").at("printSheets").at("report");require(settings.at("area")==Json({{"row1",2},{"col1",2},{"row2",50},{"col2",5}})&&settings.at("repeatHeaderRows")==Json({{"row1",2},{"row2",3}})&&settings.at("orientation")=="landscape"&&settings.at("fitWidth")==true,"native print area/titles/orientation/fit must import from prefixed XML");
 require(supportedNativePrintName(package,"_xlnm.Print_Area","0","'Sales ''26'!$B$2:$E$50"),"fully parsed native print area is safe for structural sheet updates");require(!supportedNativePrintName(package,"_xlnm.Print_Area","0","'Sales ''26'!$B$2:$E$50,'Sales ''26'!$G$1:$H$2"),"union print area must remain opaque");
 package.workbook["settings"]["printSheets"]["report"]["area"]={{"row1",1},{"col1",1},{"row2",20},{"col2",4}};writeNativePrintSettings(package.entries,package.workbook,package.sheetParts);WorkbookPackage reread=package;reread.workbook["settings"]=Json::object();readNativePrintSettings(reread);require(reread.workbook.at("settings")==package.workbook.at("settings"),"native settings must round trip with retained namespace prefixes");require(package.entries.at("xl/worksheets/sheet1.xml").find("paperSize=\"9\"")!=std::string::npos,"unowned native page attributes survive");package.entries["xl/worksheets/sheet1.xml"]="<m:worksheet xmlns:m='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><m:sheetData/><m:headerFooter><m:oddHeader>Keep</m:oddHeader></m:headerFooter></m:worksheet>";writeNativePrintSettings(package.entries,package.workbook,package.sheetParts);const auto ordered=package.entries.at("xl/worksheets/sheet1.xml");require(ordered.find("m:pageSetup")<ordered.find("m:headerFooter"),"native page setup must precede retained headerFooter in schema order");nativePackageRoundtrip();std::cout<<"native printing tests passed\n";
 }catch(const std::exception& e){std::cerr<<"native printing test failed: "<<e.what()<<'\n';return 1;}}
